  `has_teacher_of_record` BOOLEAN NOT NULL,
  `is_teacher_qualified` BOOLEAN NOT NULL,
  `required_hours_to_date` DECIMAL(7,1) NOT NULL,
  `scheduled_hours_to_date` DECIMAL(7,1) NOT NULL,
  `delivered_hours_to_date` DECIMAL(7,1) NOT NULL,
  `objectives_due` SMALLINT NOT NULL,
  `objectives_delivered` SMALLINT NOT NULL,
  `objectives_assessed_due` SMALLINT NOT NULL,
  `objectives_assessed` SMALLINT NOT NULL,
  `open_gaps` SMALLINT NOT NULL,
  `loaded_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Warehouse load time (UTC)',
  `load_batch_id` BIGINT NOT NULL COMMENT 'ETL batch that wrote the row',
  PRIMARY KEY (`tenant_id`, `date_key`, `class_key`, `subject_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DW/fact/internal] Daily coverage snapshot per class-subject — teacher of record, qualified, hours required vs scheduled vs delivered';

CREATE TABLE `fact_compliance_score` (
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `date_key` INT NOT NULL,
  `institution_key` BIGINT NOT NULL,
  `component` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'subject_coverage, teaching_hours, objectives, assessment, qualified_staff, total',
  `score` DECIMAL(7,3) NOT NULL,
  `weight` DECIMAL(6,4) NOT NULL,
  `band` VARCHAR(24) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'compliant, partial, non_compliant, not_assessed',
  `loaded_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Warehouse load time (UTC)',
  `load_batch_id` BIGINT NOT NULL COMMENT 'ETL batch that wrote the row',
  PRIMARY KEY (`tenant_id`, `date_key`, `institution_key`, `component`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DW/fact/internal] Curriculum compliance per institution per day with components (subject coverage 20, hours 25, objectives 25, assessment 15, qualified staff 15)';

CREATE TABLE `fact_coverage_gap` (
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `gap_id` BINARY(16) NOT NULL,
  `institution_key` BIGINT NOT NULL,
  `class_key` BIGINT,
  `subject_key` BIGINT,
  `rule` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `severity` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `opened_date_key` INT NOT NULL,
  `closed_date_key` INT,
  `escalation_level` SMALLINT NOT NULL,
  `learners_affected` SMALLINT NOT NULL,
  `loaded_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Warehouse load time (UTC)',
  `load_batch_id` BIGINT NOT NULL COMMENT 'ETL batch that wrote the row',
  PRIMARY KEY (`tenant_id`, `gap_id`),
  CONSTRAINT `ck_fact_coverage_gap__rule` CHECK (`rule` IN ('g1', 'g2', 'g3', 'g4', 'g5', 'g6', 'g7', 'g8', 'g9', 'g10', 'g11', 'g12')),
  CONSTRAINT `ck_fact_coverage_gap__severity` CHECK (`severity` IN ('critical', 'high', 'moderate', 'info'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DW/fact/internal] Coverage gap fact (opened, closed, age, severity, rule)';

CREATE TABLE `fact_curriculum_delivery` (
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `delivery_id` BINARY(16) NOT NULL,
