  `loaded_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Warehouse load time (UTC)',
  `load_batch_id` BIGINT NOT NULL COMMENT 'ETL batch that wrote the row',
  PRIMARY KEY (`tenant_id`, `delivery_id`, `node_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DW/fact/internal] Lesson delivery fact per objective';

CREATE TABLE `fact_data_quality` (
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `date_key` INT NOT NULL,
  `institution_key` BIGINT NOT NULL,
  `completeness` DECIMAL(7,6) NOT NULL,
  `uniqueness` DECIMAL(7,6) NOT NULL,
  `validity` DECIMAL(7,6) NOT NULL,
  `timeliness` DECIMAL(7,6) NOT NULL,
  `consistency` DECIMAL(7,6) NOT NULL,
  `verification` DECIMAL(7,6) NOT NULL,
  `dqi` DECIMAL(7,3) NOT NULL,
  `loaded_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Warehouse load time (UTC)',
  `load_batch_id` BIGINT NOT NULL COMMENT 'ETL batch that wrote the row',
  PRIMARY KEY (`tenant_id`, `date_key`, `institution_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DW/fact/internal] Data Quality Index components per institution per day (DQI = 0.30C + 0.20U + 0.20V + 0.15T + 0.10K + 0.05Ve)';

CREATE TABLE `fact_digital_skill` (
