) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DW/fact/confidential] Digital-skills level snapshot per person and strand';

CREATE TABLE `fact_digitisation` (
