  `institution_key` BIGINT NOT NULL,
  `class_key` BIGINT,
  `staff_key` BIGINT NOT NULL,
  `assignment_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `learners_expected` SMALLINT NOT NULL,
  `submitted` SMALLINT NOT NULL,
  `on_time` SMALLINT NOT NULL,
  `late` SMALLINT NOT NULL,
  `missing` SMALLINT NOT NULL,
  `marked` SMALLINT NOT NULL,
  `returned_online` SMALLINT NOT NULL,
  `loaded_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Warehouse load time (UTC)',
  `load_batch_id` BIGINT NOT NULL COMMENT 'ETL batch that wrote the row',
  PRIMARY KEY (`tenant_id`, `assignment_id`),
  CONSTRAINT `ck_fact_lms_activity__assignment_kind` CHECK (`assignment_kind` IN ('homework', 'coursework', 'ca_test', 'quiz_cbt', 'practical', 'portfolio', 'peer_review', 'digital_skills_task'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DW/fact/internal] LMS activity fact per assignment (set, submitted, on time, late, missing, marked)';

CREATE TABLE `fact_message` (
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `message_id` BINARY(16) NOT NULL,
  `date_key` INT NOT NULL,
  `institution_key` BIGINT,
  `channel` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `direction` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `is_delivered` BOOLEAN NOT NULL,
  `is_read` BOOLEAN NOT NULL,
  `response_minutes` INT,
  `cost_minor` BIGINT COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin,
  `loaded_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Warehouse load time (UTC)',
  `load_batch_id` BIGINT NOT NULL COMMENT 'ETL batch that wrote the row',
  PRIMARY KEY (`tenant_id`, `message_id`),
  CONSTRAINT `ck_fact_message__channel` CHECK (`channel` IN ('in_app', 'push', 'sms', 'whatsapp', 'email', 'voice', 'ussd', 'workspace', 'web', 'post')),
  CONSTRAINT `ck_fact_message__direction` CHECK (`direction` IN ('outbound', 'inbound'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DW/fact/internal] Messaging fact (volumes, delivery, read, cost by channel)';

