) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DW/fact/internal] SDAF fact per institution and billing period (billed, exempted, collected, remitted, outstanding)';

