CREATE TABLE `live_kpi` (
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `metric_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `scope_key` BIGINT NOT NULL,
  `as_of_date` DATE NOT NULL,
  `value` DECIMAL(18,6),
  `numerator` DECIMAL(18,6),
  `denominator` DECIMAL(18,6),
  `is_suppressed` BOOLEAN NOT NULL,
  `refreshed_at` DATETIME(6) NOT NULL,
  `loaded_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Warehouse load time (UTC)',
  `load_batch_id` BIGINT NOT NULL COMMENT 'ETL batch that wrote the row',
  PRIMARY KEY (`tenant_id`, `metric_code`, `scope_key`, `as_of_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[DW/aggregate/internal] Live KPI read model (attendance today, registers, staff presence) refreshed by stream aggregation ≤ 5 min';

